#pragma once

#ifndef QUERYOBJECT_H
#define QUERYOBJECT_H

#include "TagimgSchema.h"

namespace graphql::tagimg::object {
namespace methods::QueryHas {

template <class TImpl>
concept getPingWithParams = requires (TImpl impl, service::FieldParams params)
{
	{ service::AwaitableScalar<std::string> { impl.getPing(std::move(params)) } };
};

template <class TImpl>
concept getPing = requires (TImpl impl)
{
	{ service::AwaitableScalar<std::string> { impl.getPing() } };
};

template <class TImpl>
concept getArtworkWithParams = requires (TImpl impl, service::FieldParams params, response::IdType idArg)
{
	{ service::AwaitableObject<std::shared_ptr<Artwork>> { impl.getArtwork(std::move(params), std::move(idArg)) } };
};

template <class TImpl>
concept getArtwork = requires (TImpl impl, response::IdType idArg)
{
	{ service::AwaitableObject<std::shared_ptr<Artwork>> { impl.getArtwork(std::move(idArg)) } };
};

template <class TImpl>
concept getArtworksWithParams = requires (TImpl impl, service::FieldParams params, std::unique_ptr<ArtworkFilter> filterArg, std::optional<ArtworkOrderField> orderByArg, std::optional<SortDirection> directionArg, std::optional<int> limitArg, std::optional<int> offsetArg, std::optional<bool> includeTotalArg)
{
	{ service::AwaitableObject<std::shared_ptr<ArtworkConnection>> { impl.getArtworks(std::move(params), std::move(filterArg), std::move(orderByArg), std::move(directionArg), std::move(limitArg), std::move(offsetArg), std::move(includeTotalArg)) } };
};

template <class TImpl>
concept getArtworks = requires (TImpl impl, std::unique_ptr<ArtworkFilter> filterArg, std::optional<ArtworkOrderField> orderByArg, std::optional<SortDirection> directionArg, std::optional<int> limitArg, std::optional<int> offsetArg, std::optional<bool> includeTotalArg)
{
	{ service::AwaitableObject<std::shared_ptr<ArtworkConnection>> { impl.getArtworks(std::move(filterArg), std::move(orderByArg), std::move(directionArg), std::move(limitArg), std::move(offsetArg), std::move(includeTotalArg)) } };
};

template <class TImpl>
concept beginSelectionSet = requires (TImpl impl, const service::SelectionSetParams params)
{
	{ impl.beginSelectionSet(params) };
};

template <class TImpl>
concept endSelectionSet = requires (TImpl impl, const service::SelectionSetParams params)
{
	{ impl.endSelectionSet(params) };
};

} // namespace methods::QueryHas

class [[nodiscard("unnecessary construction")]] Query final
	: public service::Object
{
private:
	[[nodiscard("unnecessary call")]] service::AwaitableResolver resolvePing(service::ResolverParams&& params) const;
	[[nodiscard("unnecessary call")]] service::AwaitableResolver resolveArtwork(service::ResolverParams&& params) const;
	[[nodiscard("unnecessary call")]] service::AwaitableResolver resolveArtworks(service::ResolverParams&& params) const;

	[[nodiscard("unnecessary call")]] service::AwaitableResolver resolve_typename(service::ResolverParams&& params) const;
	[[nodiscard("unnecessary call")]] service::AwaitableResolver resolve_schema(service::ResolverParams&& params) const;
	[[nodiscard("unnecessary call")]] service::AwaitableResolver resolve_type(service::ResolverParams&& params) const;

	std::shared_ptr<schema::Schema> _schema;

	struct [[nodiscard("unnecessary construction")]] Concept
	{
		virtual ~Concept() = default;

		virtual void beginSelectionSet(const service::SelectionSetParams& params) const = 0;
		virtual void endSelectionSet(const service::SelectionSetParams& params) const = 0;

		[[nodiscard("unnecessary call")]] virtual service::AwaitableScalar<std::string> getPing(service::FieldParams&& params) const = 0;
		[[nodiscard("unnecessary call")]] virtual service::AwaitableObject<std::shared_ptr<Artwork>> getArtwork(service::FieldParams&& params, response::IdType&& idArg) const = 0;
		[[nodiscard("unnecessary call")]] virtual service::AwaitableObject<std::shared_ptr<ArtworkConnection>> getArtworks(service::FieldParams&& params, std::unique_ptr<ArtworkFilter>&& filterArg, std::optional<ArtworkOrderField>&& orderByArg, std::optional<SortDirection>&& directionArg, std::optional<int>&& limitArg, std::optional<int>&& offsetArg, std::optional<bool>&& includeTotalArg) const = 0;
	};

	template <class T>
	struct [[nodiscard("unnecessary construction")]] Model final
		: Concept
	{
		explicit Model(std::shared_ptr<T> pimpl) noexcept
			: _pimpl { std::move(pimpl) }
		{
		}

		[[nodiscard("unnecessary call")]] service::AwaitableScalar<std::string> getPing(service::FieldParams&& params) const override
		{
			if constexpr (methods::QueryHas::getPingWithParams<T>)
			{
				return { _pimpl->getPing(std::move(params)) };
			}
			else
			{
				static_assert(methods::QueryHas::getPing<T>, R"msg(Query::getPing is not implemented)msg");
				return { _pimpl->getPing() };
			}
		}

		[[nodiscard("unnecessary call")]] service::AwaitableObject<std::shared_ptr<Artwork>> getArtwork(service::FieldParams&& params, response::IdType&& idArg) const override
		{
			if constexpr (methods::QueryHas::getArtworkWithParams<T>)
			{
				return { _pimpl->getArtwork(std::move(params), std::move(idArg)) };
			}
			else
			{
				static_assert(methods::QueryHas::getArtwork<T>, R"msg(Query::getArtwork is not implemented)msg");
				return { _pimpl->getArtwork(std::move(idArg)) };
			}
		}

		[[nodiscard("unnecessary call")]] service::AwaitableObject<std::shared_ptr<ArtworkConnection>> getArtworks(service::FieldParams&& params, std::unique_ptr<ArtworkFilter>&& filterArg, std::optional<ArtworkOrderField>&& orderByArg, std::optional<SortDirection>&& directionArg, std::optional<int>&& limitArg, std::optional<int>&& offsetArg, std::optional<bool>&& includeTotalArg) const override
		{
			if constexpr (methods::QueryHas::getArtworksWithParams<T>)
			{
				return { _pimpl->getArtworks(std::move(params), std::move(filterArg), std::move(orderByArg), std::move(directionArg), std::move(limitArg), std::move(offsetArg), std::move(includeTotalArg)) };
			}
			else
			{
				static_assert(methods::QueryHas::getArtworks<T>, R"msg(Query::getArtworks is not implemented)msg");
				return { _pimpl->getArtworks(std::move(filterArg), std::move(orderByArg), std::move(directionArg), std::move(limitArg), std::move(offsetArg), std::move(includeTotalArg)) };
			}
		}

		void beginSelectionSet(const service::SelectionSetParams& params) const override
		{
			if constexpr (methods::QueryHas::beginSelectionSet<T>)
			{
				_pimpl->beginSelectionSet(params);
			}
		}

		void endSelectionSet(const service::SelectionSetParams& params) const override
		{
			if constexpr (methods::QueryHas::endSelectionSet<T>)
			{
				_pimpl->endSelectionSet(params);
			}
		}

	private:
		const std::shared_ptr<T> _pimpl;
	};

	explicit Query(std::unique_ptr<const Concept> pimpl) noexcept;

	[[nodiscard("unnecessary call")]] service::TypeNames getTypeNames() const noexcept;
	[[nodiscard("unnecessary call")]] service::ResolverMap getResolvers() const noexcept;

	void beginSelectionSet(const service::SelectionSetParams& params) const override;
	void endSelectionSet(const service::SelectionSetParams& params) const override;

	const std::unique_ptr<const Concept> _pimpl;

public:
	template <class T>
	explicit Query(std::shared_ptr<T> pimpl) noexcept
		: Query { std::unique_ptr<const Concept> { std::make_unique<Model<T>>(std::move(pimpl)) } }
	{
	}

	[[nodiscard("unnecessary call")]] static constexpr std::string_view getObjectType() noexcept
	{
		return { R"gql(Query)gql" };
	}
};

} // namespace graphql::tagimg::object

#endif // QUERYOBJECT_H
